def semantic_function(ctx):
    '''Compute the last day to serve an answer after service of the summons and complaint under the governing procedural rule.'''
    narrate(ctx, 'Computing the last day to serve an answer after service of the summons and complaint')
    service_text = load(ctx, 'the calendar date on which the summons and complaint were served on the defendant, including weekday if given', d_type=str)
    waiver_text = load(ctx, 'the waiver status of service for the defendant, stating whether the defendant waived formal service or not', d_type=str)
    rule_text = load(ctx, 'the governing procedural rule that sets the time to serve an answer, cited by rule number', d_type=str)
    narrate(ctx, 'Loaded service date: ' + str(service_text))
    narrate(ctx, 'Loaded waiver status: ' + str(waiver_text))
    narrate(ctx, 'Loaded governing rule: ' + str(rule_text))
    parsed = do(ctx, 'Parse the calendar date text of service into a calendar date value', payloads={'the calendar date on which the summons and complaint were served on the defendant, including weekday if given': service_text})
    service_date = load(parsed, 'the parsed service date', d_type=str, ctx=ctx)
    narrate(ctx, 'Parsed service date: ' + str(service_date))
    period_result = do(ctx, 'Determine the number of days allowed to serve an answer given the waiver status of service under the governing rule', payloads={'the waiver status of service for the defendant, stating whether the defendant waived formal service or not': waiver_text, 'the governing procedural rule that sets the time to serve an answer, cited by rule number': rule_text})
    period = load(period_result, 'the response period in days', d_type=int, ctx=ctx)
    narrate(ctx, 'Response period: ' + str(period) + ' days')
    nominal_result = do(ctx, 'Count calendar days forward from the parsed service date, excluding the service day, to get the nominal answer deadline', payloads={'the parsed service date': service_date, 'the response period in days': period})
    nominal = load(nominal_result, 'the nominal deadline date', d_type=str, ctx=ctx)
    narrate(ctx, 'Nominal deadline: ' + str(nominal))
    adjusted_result = do(ctx, 'Advance a nominal deadline date forward to the next day that is not a weekend day or federal legal holiday', payloads={'the nominal deadline date': nominal})
    final_date = load(adjusted_result, 'the adjusted last day to serve an answer', d_type=str, ctx=ctx)
    narrate(ctx, 'Adjusted last day to serve an answer: ' + str(final_date))
    weekday_result = do(ctx, 'Determine the weekday name of a calendar date', payloads={'the calendar date': final_date})
    weekday = load(weekday_result, 'the weekday name of the date', d_type=str, ctx=ctx)
    narrate(ctx, 'The last day to serve an answer falls on a ' + str(weekday))
    return {'the last day to serve an answer': final_date, 'the weekday of the last day to serve an answer': weekday}
